import { StyleSheet } from 'react-native';
import { spacing } from '../theme';

export default StyleSheet.create({
  container: {
    padding: spacing.lg,
    borderRadius: 24,
    marginBottom: spacing.lg,
    shadowColor: '#00D4FF',
    shadowOffset: { width: 0, height: 10 },
    shadowOpacity: 0.2,
    shadowRadius: 25,
    elevation: 6,
  },
  title: {
    color: '#FFFFFF',
    fontSize: 24,
    fontWeight: '800',
  },
  subtitle: {
    color: '#D2E9FF',
    fontSize: 14,
    marginTop: spacing.xs,
  },
});
